function positionMarkUsd(p){const asset=BY_SYMBOL[p.symbol]||{quote:'USD'},px=prices[p.symbol],gross=Number.isFinite(px)?positionValueUsd(asset,px,p.qty):NaN;if(!Number.isFinite(gross))return NaN;if((p.side||'long')==='short'){const rate=quoteUsdRate(asset.quote),move=(p.entry-px)*p.qty*rate,margin=p.marginUsd??p.entryGrossUsd??p.entry*p.qty*(p.entryFxRate||1);return margin+move-gross*FEE}return gross*(1-FEE)}
